import React, { useEffect, useState, useRef } from 'react';
import api from '../utils/api';
import Chart from 'chart.js/auto';

const ChartComponent = () => {
    const [aircraftData, setAircraftData] = useState({});
    const [selectedAircraft, setSelectedAircraft] = useState('');
    const [startDate, setStartDate] = useState('2023-01-01');
    const [endDate, setEndDate] = useState('2024-01-01');
    const [error, setError] = useState(null);
    const chartRef = useRef(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                // Assume api.getData() fetches data in the correct format
                const result = await api.getData();
                // Data processing logic assumed to be correctly implemented
                const organizedData = organizeDataByAircraft(result.data);
                setAircraftData(organizedData);
                updateChart(organizedData);
            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        fetchData();
    }, []);

    useEffect(() => {
        updateChart(aircraftData);
    }, [selectedAircraft, startDate, endDate, aircraftData]);

    const updateChart = (data) => {
        const aircraft = data[selectedAircraft];
        if (!aircraft || !chartRef.current) return;

        const filteredData = Object.entries(aircraft).filter(([date]) => date >= startDate && date <= endDate);
        const labels = filteredData.map(([date]) => date);
        const revenueData = filteredData.map(([date, details]) => details.Price / details.FlightHrs);

        const ctx = chartRef.current.getContext('2d');
        if (chartRef.current.chartInstance) {
            chartRef.current.chartInstance.destroy();
        }
        chartRef.current.chartInstance = new Chart(ctx, {
            type: 'bar',
            data: {
                labels,
                datasets: [{
                    label: `Revenue Per Hour for ${selectedAircraft}`,
                    data: revenueData,
                    backgroundColor: 'rgba(75, 192, 192, 0.2)',
                    borderColor: 'rgba(75, 192, 192, 1)',
                    borderWidth: 1
                }]
            },
            options: {
                scales: {
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: 'Revenue Per Hour ($)'
                        }
                    },
                    x: {
                        title: {
                            display: true,
                            text: 'Date'
                        }
                    }
                }
            }
        });
    };

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div>
            <h1>Aircraft Revenue Analysis</h1>
            <div>
                Select Aircraft:
                <select value={selectedAircraft} onChange={e => setSelectedAircraft(e.target.value)}>
                    {Object.keys(aircraftData).map(aircraft => (
                        <option key={aircraft} value={aircraft}>{aircraft}</option>
                    ))}
                </select>
                Start Date:
                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} />
                End Date:
                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} />
            </div>
            <canvas ref={chartRef}></canvas>
        </div>
    );
};

export default ChartComponent;
